import java.io.*;
import java.util.*;
import java.util.jar.*;
import org.objectweb.asm.*;
import org.objectweb.asm.tree.*;
public class InspectCombat implements Opcodes {
 static byte[] read(InputStream in)throws Exception{ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] x=new byte[8192];int n;while((n=in.read(x))!=-1)b.write(x,0,n);in.close();return b.toByteArray();}
 static ClassNode cls(byte[] b){ClassNode n=new ClassNode();new ClassReader(b).accept(n,0);return n;}
 static List<AbstractInsnNode> real(MethodNode m){List<AbstractInsnNode> r=new ArrayList<AbstractInsnNode>();for(AbstractInsnNode i:m.instructions.toArray())if(i.getOpcode()>=0)r.add(i);return r;}
 static boolean hasString(ClassNode c,String s){for(MethodNode m:c.methods)for(AbstractInsnNode i:m.instructions.toArray())if(i instanceof LdcInsnNode&&s.equals(((LdcInsnNode)i).cst))return true;return false;}
 static boolean rangeScale(MethodNode m,String base){List<AbstractInsnNode> x=real(m);for(int i=0;i+4<x.size();i++)if(x.get(i) instanceof FieldInsnNode&&x.get(i).getOpcode()==GETFIELD&&base.equals(((FieldInsnNode)x.get(i)).owner)&&"I".equals(((FieldInsnNode)x.get(i)).desc)&&isInt(x.get(i+1),3)&&x.get(i+2).getOpcode()==IMUL&&isInt(x.get(i+3),2)&&x.get(i+4).getOpcode()==IDIV)return true;return false;}
 static boolean isInt(AbstractInsnNode i,int v){if(i==null)return false;if(i.getOpcode()>=ICONST_M1&&i.getOpcode()<=ICONST_5)return i.getOpcode()-ICONST_0==v;if(i instanceof IntInsnNode)return ((IntInsnNode)i).operand==v;return i instanceof LdcInsnNode&&Integer.valueOf(v).equals(((LdcInsnNode)i).cst);}
 static void dump(ClassNode c,MethodNode m){System.out.println("METHOD "+c.name+"."+m.name+m.desc+" access="+m.access+" instructions="+real(m).size());int n=0;for(AbstractInsnNode i:m.instructions.toArray()){if(i.getOpcode()<0)continue;System.out.print(String.format("%04d op=%d",n++,i.getOpcode()));if(i instanceof FieldInsnNode){FieldInsnNode f=(FieldInsnNode)i;System.out.print(" FIELD "+f.owner+"."+f.name+" "+f.desc);}else if(i instanceof MethodInsnNode){MethodInsnNode x=(MethodInsnNode)i;System.out.print(" CALL "+x.owner+"."+x.name+x.desc);}else if(i instanceof VarInsnNode)System.out.print(" VAR "+((VarInsnNode)i).var);else if(i instanceof IntInsnNode)System.out.print(" INT "+((IntInsnNode)i).operand);else if(i instanceof LdcInsnNode)System.out.print(" LDC "+((LdcInsnNode)i).cst);else if(i instanceof JumpInsnNode)System.out.print(" JUMP");System.out.println();}}
 public static void main(String[] a)throws Exception{JarFile j=new JarFile(a[0]);Map<String,ClassNode> cs=new LinkedHashMap<String,ClassNode>();Enumeration<JarEntry> e=j.entries();while(e.hasMoreElements()){JarEntry z=e.nextElement();if(z.getName().endsWith(".class")){ClassNode c=cls(read(j.getInputStream(z)));cs.put(c.name,c);}}j.close();for(ClassNode p:cs.values())if(hasString(p,"Player vec7")){System.out.println("PLAYER="+p.name+" BASE="+p.superName);for(MethodNode m:p.methods)if(rangeScale(m,p.superName))dump(p,m);for(MethodNode m:p.methods){for(AbstractInsnNode i:m.instructions.toArray())if(i instanceof MethodInsnNode){MethodInsnNode x=(MethodInsnNode)i;if(p.name.equals(x.owner))for(MethodNode mm:p.methods)if(mm.name.equals(x.name)&&mm.desc.equals(x.desc)&&"()V".equals(mm.desc)){System.out.println("CALLEE from "+m.name+m.desc+":");dump(p,mm);}}}}}
}
